import media from './mad-media.json';

/** Approved photography, generated by scripts/collect_instagram.py from the asset manifest. */
export const photo = id => {
  const item = media[id];
  if (!item) throw new Error(`Unknown photograph: ${id}`);
  return item;
};

/** Props for a responsive <img>: 1000w and 2000w WebP renditions with intrinsic size. */
export const imgProps = (id, sizes = '100vw') => {
  const item = photo(id);
  const smallWidth = Math.round(item.width * Math.min(1, 1000 / Math.max(item.width, item.height)));
  return {
    src: item.src,
    srcSet: `${item.small} ${smallWidth}w, ${item.src} ${item.width}w`,
    sizes,
    width: item.width,
    height: item.height,
    alt: item.alt,
  };
};

export const credit = id => {
  const item = photo(id);
  return item.credit ? `Image: ${item.credit}` : 'Image: M.A.D. Collaboratives';
};
